/**
 * Naadopaasana Interactive Gamaka & Svara Game Loop Engine
 * Full 60 FPS HTML5 Canvas renderer with real-time audio pitch tracking,
 * dynamic spline ribbon rendering, particle burst emitter, and dual scoring.
 */
class GamakaCanvasGameEngine {
  constructor(canvasElement, options = {}) {
    this.canvas = canvasElement;
    this.ctx = canvasElement.getContext('2d');
    this.options = options;

    // Display scaling for Retina / High-DPI screens
    this.dpr = window.devicePixelRatio || 1;
    this.width = canvasElement.clientWidth || 800;
    this.height = canvasElement.clientHeight || 450;
    this.canvas.width = this.width * this.dpr;
    this.canvas.height = this.height * this.dpr;
    this.ctx.scale(this.dpr, this.dpr);

    // Game State
    this.isRunning = false;
    this.activeExercise = null;
    this.currentTimeMs = 0;
    this.totalDurationMs = 2000;
    this.kattaiRootHz = options.kattaiRootHz || 261.63; // 1 Kattai C

    // Player Avatar Physics
    this.avatar = {
      x: 120, // fixed horizontal flight line
      y: this.height / 2,
      targetY: this.height / 2,
      lerp: 0.18,
      radius: 14,
      color: '#10B981',
      sparkles: []
    };

    // Live Audio Input State
    this.currentDetectedCents = null;
    this.currentConfidence = 0.0;
    this.centsTolerance = options.toleranceCents || 35.0;

    // Score & Combo Telemetry
    this.score = 0;
    this.comboMultiplier = 1.0;
    this.streakFrames = 0;
    this.starsCollected = 0;
    this.totalStarsAvailable = 0;
    this.boundaryViolations = 0;
    this.pointsCollected = [];

    // Particle System
    this.particles = [];
  }

  centsToY(cents) {
    const minCents = -100;
    const maxCents = 1300;
    const norm = (cents - minCents) / (maxCents - minCents);
    return this.height * (1.0 - (norm * 0.75 + 0.12));
  }

  loadExercise(exerciseData) {
    this.activeExercise = exerciseData;
    this.totalDurationMs = exerciseData.visual_stencil.duration_ms || 2400;
    this.currentTimeMs = 0;
    this.score = 0;
    this.comboMultiplier = 1.0;
    this.streakFrames = 0;
    this.starsCollected = 0;
    this.boundaryViolations = 0;
    this.particles = [];

    this.waypoints = (exerciseData.game_meta && exerciseData.game_meta.star_waypoints) 
      ? JSON.parse(JSON.stringify(exerciseData.game_meta.star_waypoints))
      : [];
    this.totalStarsAvailable = this.waypoints.length;
  }

  feedMicrophonePitch(detectedHz, confidence = 0.9) {
    this.currentConfidence = confidence;
    if (!detectedHz || detectedHz <= 0 || confidence < 0.75) {
      this.currentDetectedCents = null;
      return;
    }
    const cents = 1200.0 * Math.log2(detectedHz / this.kattaiRootHz);
    this.currentDetectedCents = cents;
    this.avatar.targetY = this.centsToY(cents);
  }

  update(deltaTimeMs) {
    if (!this.isRunning || !this.activeExercise) return;

    this.currentTimeMs += deltaTimeMs;
    if (this.currentTimeMs > this.totalDurationMs + 800) {
      this.completeGame();
      return;
    }

    this.avatar.y += (this.avatar.targetY - this.avatar.y) * this.avatar.lerp;

    const targetCents = this.interpolateTargetCents(this.currentTimeMs);
    const upperCeiling = targetCents + this.centsTolerance;
    const lowerFloor = targetCents - this.centsTolerance;

    if (this.currentDetectedCents !== null) {
      const error = Math.abs(this.currentDetectedCents - targetCents);
      if (error <= this.centsTolerance) {
        this.streakFrames++;
        if (this.streakFrames > 90) this.comboMultiplier = 3.0;
        else if (this.streakFrames > 45) this.comboMultiplier = 2.0;
        else if (this.streakFrames > 20) this.comboMultiplier = 1.5;

        this.score += Math.round(10 * this.comboMultiplier);
        this.avatar.color = '#10B981';

        if (Math.random() < 0.4) {
          this.emitParticle(this.avatar.x, this.avatar.y, '#FDE047', 1.2, 0.8);
        }
      } else {
        if (this.currentDetectedCents > upperCeiling + 40 || this.currentDetectedCents < lowerFloor - 40) {
          this.boundaryViolations++;
          this.avatar.color = '#EF4444';
        } else {
          this.avatar.color = '#F59E0B';
        }
        this.comboMultiplier = 1.0;
        this.streakFrames = 0;
      }
    } else {
      this.avatar.color = '#64748B';
      this.comboMultiplier = 1.0;
    }

    this.checkWaypointCollisions(targetCents);

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= 0.035;
      if (p.life <= 0) this.particles.splice(i, 1);
    }
  }

  interpolateTargetCents(t) {
    const pts = this.activeExercise.visual_stencil.trajectory_points;
    if (!pts || pts.length === 0) return 0;
    if (t <= pts[0].t_ms) return pts[0].cents;
    if (t >= pts[pts.length - 1].t_ms) return pts[pts.length - 1].cents;

    for (let i = 0; i < pts.length - 1; i++) {
      if (t >= pts[i].t_ms && t <= pts[i + 1].t_ms) {
        const span = pts[i + 1].t_ms - pts[i].t_ms;
        const alpha = (t - pts[i].t_ms) / (span || 1);
        return pts[i].cents + alpha * (pts[i + 1].cents - pts[i].cents);
      }
    }
    return pts[0].cents;
  }

  checkWaypointCollisions(targetCents) {
    if (!this.waypoints) return;
    this.waypoints.forEach(wp => {
      if (!wp.collected && Math.abs(this.currentTimeMs - wp.t_ms) < 70) {
        if (this.currentDetectedCents !== null && Math.abs(this.currentDetectedCents - wp.cents) <= (wp.tolerance_cents || this.centsTolerance)) {
          wp.collected = true;
          this.starsCollected++;
          this.score += (wp.star_value || 100) * this.comboMultiplier;
          this.triggerStarBurst(this.avatar.x, this.avatar.y);
        }
      }
    });
  }

  emitParticle(x, y, color, speed = 2, size = 3) {
    this.particles.push({
      x, y,
      vx: (Math.random() - 0.5) * speed,
      vy: (Math.random() - 0.5) * speed,
      color,
      size,
      life: 1.0
    });
  }

  triggerStarBurst(x, y) {
    for (let i = 0; i < 18; i++) {
      const angle = (Math.PI * 2 / 18) * i;
      const spd = 2.5 + Math.random() * 3.5;
      this.particles.push({
        x, y,
        vx: Math.cos(angle) * spd,
        vy: Math.sin(angle) * spd,
        color: i % 2 === 0 ? '#FBBF24' : '#60A5FA',
        size: 4 + Math.random() * 3,
        life: 1.0
      });
    }
  }

  render() {
    this.ctx.clearRect(0, 0, this.width, this.height);
    this.drawBackgroundGrid();
    if (this.activeExercise) {
      this.drawToleranceRibbon();
      this.drawWaypoints();
    }
    this.drawAvatar();
    this.drawParticles();
    this.drawHUD();
  }

  drawBackgroundGrid() {
    const swaras = [
      { name: 'S', cents: 0 },
      { name: 'R1', cents: 112 },
      { name: 'G3', cents: 386 },
      { name: 'M1', cents: 498 },
      { name: 'P', cents: 702 },
      { name: 'D1', cents: 814 },
      { name: 'N3', cents: 1088 },
      { name: 'Ṡ', cents: 1200 }
    ];

    this.ctx.strokeStyle = 'rgba(226, 232, 240, 0.45)';
    this.ctx.lineWidth = 1;
    this.ctx.font = '11px sans-serif';
    this.ctx.fillStyle = '#94A3B8';

    swaras.forEach(sw => {
      const y = this.centsToY(sw.cents);
      this.ctx.beginPath();
      this.ctx.moveTo(0, y);
      this.ctx.lineTo(this.width, y);
      this.ctx.stroke();
      this.ctx.fillText(`${sw.name} (${sw.cents}c)`, 12, y - 4);
    });
  }

  drawToleranceRibbon() {
    const pts = this.activeExercise.visual_stencil.trajectory_points;
    if (!pts || pts.length < 2) return;

    const timeToX = (t) => {
      return this.avatar.x + ((t - this.currentTimeMs) / 1000) * 220;
    };

    this.ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      const x = timeToX(pts[i].t_ms);
      const y = this.centsToY(pts[i].cents + this.centsTolerance);
      if (i === 0) this.ctx.moveTo(x, y);
      else this.ctx.lineTo(x, y);
    }
    for (let i = pts.length - 1; i >= 0; i--) {
      const x = timeToX(pts[i].t_ms);
      const y = this.centsToY(pts[i].cents - this.centsTolerance);
      this.ctx.lineTo(x, y);
    }
    this.ctx.closePath();
    this.ctx.fillStyle = 'rgba(14, 165, 233, 0.22)';
    this.ctx.fill();

    this.ctx.beginPath();
    pts.forEach((pt, idx) => {
      const x = timeToX(pt.t_ms);
      const y = this.centsToY(pt.cents);
      if (idx === 0) this.ctx.moveTo(x, y);
      else this.ctx.lineTo(x, y);
    });
    this.ctx.strokeStyle = '#0284C7';
    this.ctx.lineWidth = 3;
    this.ctx.stroke();
  }

  drawWaypoints() {
    if (!this.waypoints) return;
    const timeToX = (t) => this.avatar.x + ((t - this.currentTimeMs) / 1000) * 220;

    this.waypoints.forEach(wp => {
      const x = timeToX(wp.t_ms);
      const y = this.centsToY(wp.cents);
      if (x < -20 || x > this.width + 20) return;

      this.ctx.save();
      this.ctx.translate(x, y);
      if (wp.collected) {
        this.ctx.fillStyle = 'rgba(251, 191, 36, 0.4)';
        this.ctx.beginPath();
        this.ctx.arc(0, 0, 6, 0, Math.PI * 2);
        this.ctx.fill();
      } else {
        this.ctx.fillStyle = '#F59E0B';
        this.ctx.shadowColor = '#FBBF24';
        this.ctx.shadowBlur = 10;
        this.drawStarPath(0, 0, 5, 11, 5);
        this.ctx.fill();
      }
      this.ctx.restore();
    });
  }

  drawStarPath(cx, cy, spikes, outerRadius, innerRadius) {
    let rot = Math.PI / 2 * 3;
    let x = cx;
    let y = cy;
    let step = Math.PI / spikes;

    this.ctx.beginPath();
    this.ctx.moveTo(cx, cy - outerRadius);
    for (let i = 0; i < spikes; i++) {
      x = cx + Math.cos(rot) * outerRadius;
      y = cy + Math.sin(rot) * outerRadius;
      this.ctx.lineTo(x, y);
      rot += step;
      x = cx + Math.cos(rot) * innerRadius;
      y = cy + Math.sin(rot) * innerRadius;
      this.ctx.lineTo(x, y);
      rot += step;
    }
    this.ctx.lineTo(cx, cy - outerRadius);
    this.ctx.closePath();
  }

  drawAvatar() {
    this.ctx.save();
    this.ctx.translate(this.avatar.x, this.avatar.y);
    this.ctx.fillStyle = this.avatar.color;
    this.ctx.shadowColor = this.avatar.color;
    this.ctx.shadowBlur = 14;
    this.ctx.beginPath();
    this.ctx.arc(0, 0, this.avatar.radius, 0, Math.PI * 2);
    this.ctx.fill();

    this.ctx.fillStyle = '#FFFFFF';
    this.ctx.beginPath();
    this.ctx.arc(0, 0, this.avatar.radius * 0.4, 0, Math.PI * 2);
    this.ctx.fill();
    this.ctx.restore();
  }

  drawParticles() {
    this.particles.forEach(p => {
      this.ctx.save();
      this.ctx.globalAlpha = Math.max(0, p.life);
      this.ctx.fillStyle = p.color;
      this.ctx.beginPath();
      this.ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
      this.ctx.fill();
      this.ctx.restore();
    });
  }

  drawHUD() {
    this.ctx.fillStyle = 'rgba(15, 23, 42, 0.75)';
    this.ctx.fillRect(this.width - 240, 16, 220, 72);

    this.ctx.fillStyle = '#F8FAFC';
    this.ctx.font = 'bold 18px sans-serif';
    this.ctx.fillText(`Score: ${this.score}`, this.width - 225, 42);

    this.ctx.font = '13px sans-serif';
    this.ctx.fillStyle = '#FBBF24';
    this.ctx.fillText(`Stars: ${this.starsCollected} / ${this.totalStarsAvailable}`, this.width - 225, 64);

    if (this.comboMultiplier > 1.0) {
      this.ctx.fillStyle = '#34D399';
      this.ctx.font = 'bold 14px sans-serif';
      this.ctx.fillText(`${this.comboMultiplier.toFixed(1)}x Combo!`, this.width - 110, 64);
    }
  }

  completeGame() {
    this.isRunning = false;
    const finalScoreReport = this.calculateFinalScore();
    if (this.options.onGameComplete) {
      this.options.onGameComplete(finalScoreReport);
    }
  }

  calculateFinalScore() {
    const starRatio = this.totalStarsAvailable > 0 ? (this.starsCollected / this.totalStarsAvailable) : 1.0;
    let starRating = 1;
    if (starRatio >= 0.85 && this.boundaryViolations <= 1) starRating = 3;
    else if (starRatio >= 0.60 && this.boundaryViolations <= 3) starRating = 2;

    return {
      exerciseId: this.activeExercise ? this.activeExercise.id : 'unknown',
      score: this.score,
      starsCollected: this.starsCollected,
      totalStars: this.totalStarsAvailable,
      starRating,
      boundaryViolations: this.boundaryViolations,
      accuracyPercentage: Math.round(starRatio * 100),
      cognitiveBadge: starRating === 3 ? 'Nāda Vilāsam! (Gold)' : (starRating === 2 ? 'Śubham! (Silver)' : 'Abhyāsa (Bronze)')
    };
  }
}

realtime_evaluation_and_scoring_engine.client_javascript_scoring_snippet:
function evaluateGamakaPerformance(userPitchTrack, stencilTrajectory, level = 'level_1_beginner') {
  // 1. Resample and align time frames
  const N = stencilTrajectory.length;
  let totalCentsError = 0;
  let boundaryViolations = 0;

  for (let i = 0; i < N; i++) {
    const target = stencilTrajectory[i];
    const userPoint = userPitchTrack[i] || userPitchTrack[userPitchTrack.length - 1];
    const err = Math.abs(userPoint.cents - target.cents);
    totalCentsError += err;

    // Check boundary compliance
    if (target.max_cents && userPoint.cents > target.max_cents) boundaryViolations++;
    if (target.min_cents && userPoint.cents < target.min_cents) boundaryViolations++;
  }

  const avgCentsError = totalCentsError / N;
  let contourScore = Math.max(0, 100 - (avgCentsError * 1.5));
  let penalty = boundaryViolations * 5.0;
  let finalScore = Math.round(Math.max(0, contourScore - penalty));

  return {
    score: finalScore,
    average_cents_deviation: Math.round(avgCentsError * 10) / 10,
    boundary_violations: boundaryViolations,
    tier_achieved: finalScore >= 85 ? 'GOLD' : (finalScore >= 70 ? 'SILVER' : 'BRONZE')
  };
}
